    # rev 升序（历史本就按分配序追加），项键序 rev,config，config
    # 复用 ce 的逐层键序与值格式。O(16(B+M+T+Q))。
    results.append(
        {
            "op": "cl",
            "current": (
                commit_history[-1][0] if commit_history else None
            ),
            "commits": [
                {"rev": rev, "config": snapshot}
                for rev, snapshot in commit_history
            ],
        }
    )

elif op[0] == "al":
    # 配置变更审计（只读，不推进时钟）：events 按 rev 升序（deque
    # 本就按分配序追加、仅留最近 64 条），事件为保留快照（逐项浅
    # 拷贝，叶值皆 int/str/None，追加后不再变更），项精确键序
    # rev,now,kind,section,before,after。初始为空；重复查询逐字节
    # 相同。O(A)，A≤64。
    results.append(
        {
            "op": "al",
            "events": [dict(event) for event in audit_events],
        }
    )

